/* Assignment 3 test: golden FCFS and nearest-stop-first scheduling cases.
 * Hand-calculated waits, deliveries, preemptions and capacity failures are exact.
 * Rush invariants and byte-identical frames also verify safety and determinism.
 * No process or semaphore timing can influence these pure-engine tests. */
#include "core.h"
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#define CHECK(x,n) do{if(x)printf("PASS %s\n",n);else{printf("FAIL %s\n",n);fails++;}}while(0)
static Scenario make(int cap,const int rows[][4],int n){Scenario s={0};s.floors=10;s.lifts=1;s.capacity=cap;s.tick_ms=1;s.start[0]=0;s.passenger_count=n;snprintf(s.name,sizeof s.name,"golden");for(int i=0;i<n;i++)s.passenger[i]=(PassengerSpec){rows[i][0],rows[i][1],rows[i][2],rows[i][3]};return s;}
static int run_golden(Scenario*s,Policy p,const int wait[],const int deliver[],double aw,double at,int makespan,int pre,int full){Core*c=calloc(1,sizeof* c);if(!c)return 0;CoreCallbacks cb={0};core_init(c,s,p,cb);int ok=core_run(c,500)==0;Metrics m;core_metrics(c,&m);for(int i=0;i<s->passenger_count;i++)ok=ok&&c->passenger[i].board_tick-c->passenger[i].arrival==wait[i]&&c->passenger[i].deliver_tick==deliver[i];ok=ok&&fabs(m.avg_wait-aw)<.001&&fabs(m.avg_total-at)<.001&&m.makespan==makespan&&m.preempts==pre&&m.full_events==full;if(!ok){printf("  got avgWait=%.3f avgTotal=%.3f makespan=%d preempts=%d full=%d\n",m.avg_wait,m.avg_total,m.makespan,m.preempts,m.full_events);for(int i=0;i<s->passenger_count;i++)printf("  P%d wait=%d deliver=%d\n",c->passenger[i].id,c->passenger[i].board_tick-c->passenger[i].arrival,c->passenger[i].deliver_tick);}free(c);return ok;}
static int rush_check(Scenario*s,Policy p,char*err,unsigned z){Core*x=calloc(1,sizeof*x),*y=calloc(1,sizeof*y);if(!x||!y){free(x);free(y);return 0;}core_init(x,s,p,(CoreCallbacks){0});core_init(y,s,p,(CoreCallbacks){0});int ok=core_run(x,MAX_TICKS)==0&&core_run(y,MAX_TICKS)==0&&core_validate(x,err,z)==0&&x->frame_count==y->frame_count&&memcmp(x->frames,y->frames,(size_t)x->frame_count*sizeof(Frame))==0;free(x);free(y);return ok;}
int main(void){int fails=0;const int a[][4]={{1,0,8,9},{2,0,2,3},{3,0,5,6}},awf[]={8,15,19},adf[]={24,31,35},awn[]={12,2,7},adn[]={14,4,9};Scenario sa=make(6,a,3);CHECK(run_golden(&sa,POLICY_FCFS,awf,adf,14,30,35,0,0),"scenario A FCFS");CHECK(run_golden(&sa,POLICY_NEAREST,awn,adn,7,9,14,0,0),"scenario A nearest");const int b[][4]={{1,0,8,9},{2,2,4,5}},bwf[]={8,11},bdf[]={19,24},bwn[]={10,2},bdn[]={12,6};Scenario sb=make(6,b,2);CHECK(run_golden(&sb,POLICY_FCFS,bwf,bdf,9.5,20.5,24,0,0),"scenario B FCFS");CHECK(run_golden(&sb,POLICY_NEAREST,bwn,bdn,6,8,12,1,0),"scenario B nearest");const int cc[][4]={{1,0,1,5},{2,0,1,5},{3,0,1,5}},cw[]={1,1,11},cd[]={6,6,16};Scenario sc=make(2,cc,3);CHECK(run_golden(&sc,POLICY_FCFS,cw,cd,13.0/3.0,28.0/3.0,16,0,1),"scenario C FCFS capacity");CHECK(run_golden(&sc,POLICY_NEAREST,cw,cd,13.0/3.0,28.0/3.0,16,0,1),"scenario C nearest capacity");char err[256];Scenario rush;if(!scenario_load("scenarios/rush_morning.csv",&rush,err,sizeof err)){CHECK(rush_check(&rush,POLICY_FCFS,err,sizeof err),"rush FCFS invariants and determinism");CHECK(rush_check(&rush,POLICY_NEAREST,err,sizeof err),"rush nearest invariants and determinism");}else CHECK(0,"load rush scenario");return fails?1:0;}
